import { get, filesOf, sceneOf, rowsOf, tokensOf } from './app'

const SCENE = {
  id: 'clock',
  name: 'Clock',
  settings: { execution: 'interpreted' },
  fields: [],
  nodes: [
    { id: 'render', type: 'event', data: { keyword: 'render' } },
    { id: 'app', type: 'app', data: { keyword: 'clockFace', config: {} } },
    { id: 'c1', type: 'code', data: { codeJS: 'return new Date().getHours()' } },
  ],
  edges: [],
  apps: {
    clockFace: {
      name: 'Clock face',
      version: '1.0.0',
      sources: {
        'config.json': '{\n  "name": "Clock face",\n  "version": "1.0.0"\n}\n',
        'app.tsx': "export function get() {\n  return <div>12:00</div>\n}\n",
      },
    },
  },
}

const FACTS = { busy: '', error: '', done: '', draft: null, ask: true, save: true }

function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  if (typeof node.type === 'function') return find(node.type(node.props), test)
  return node.props ? find(node.props.children, test) : null
}

// The tree with every component rendered, so its texts and handlers show.
function expand(node: any): any {
  if (!node || typeof node !== 'object') return node
  if (Array.isArray(node)) return node.map(expand)
  if (typeof node.type === 'function') return expand(node.type(node.props))
  if (!node.props) return node
  return { ...node, props: { ...node.props, children: expand(node.props.children) } }
}

const render = (app: any) => expand(get(app, makeContext()))
// Code is drawn with non-breaking spaces, so its indentation stays.
const screen = (app: any) => texts(render(app)).join('').replace(/\u00a0/g, ' ')
const button = (app: any, label: string) =>
  find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).join('') === label)
const tap = (app: any, label: string) => {
  const hit = button(app, label)
  if (!hit) throw new Error('no button ' + label + ' in ' + screen(app))
  hit.props.onClick({})
}

function host(sources: Record<string, any>, facts: any = FACTS) {
  return mock.code((op: string, arg: any) => {
    if (op === 'read') return facts
    if (op === 'source') return sources[arg] || null
    if (op === 'draft') return sources['\u0001draft'] || null
    return true
  })
}

describe('the files of a scene', () => {
  it('splits a scene into files and puts it back the same', () => {
    const { files, order } = filesOf(SCENE)
    expect(order).toEqual(['scene.json', 'clockFace/config.json', 'clockFace/app.tsx', 'code/c1.js'])
    expect(files['scene.json']).not.toContain('getHours')
    expect(files['scene.json']).not.toContain('<div>')
    expect(files['code/c1.js']).toBe('return new Date().getHours()')
    const back = sceneOf(SCENE, files)
    expect(back.scene).toEqual(SCENE)
  })

  it('takes edits back into the scene, config.json included', () => {
    const { files } = filesOf(SCENE)
    files['clockFace/app.tsx'] = 'export function get() { return <div>13:00</div> }'
    files['clockFace/config.json'] = '{"name": "Clock face", "version": "1.1.0"}'
    files['code/c1.js'] = 'return 1'
    const back = sceneOf(SCENE, files).scene
    expect(back.apps.clockFace.sources['app.tsx']).toContain('13:00')
    expect(back.apps.clockFace.version).toBe('1.1.0')
    expect(back.nodes[2].data.codeJS).toBe('return 1')
  })

  it('says where a JSON file does not parse', () => {
    const { files } = filesOf(SCENE)
    files['scene.json'] = '{ "id": '
    expect(sceneOf(SCENE, files).error).toContain('scene.json')
    const again = filesOf(SCENE).files
    again['clockFace/config.json'] = 'nope'
    expect(sceneOf(SCENE, again).error).toContain('clockFace/config.json')
  })
})

describe('the code, colored', () => {
  it('reads keywords, strings, numbers, calls and comments', () => {
    const { tokens } = tokensOf("const x = fetch('a', 42) // why", 'TypeScript', false)
    const kinds = tokens.filter((t: any) => t.t.trim()).map((t: any) => t.k + ':' + t.t.trim())
    expect(kinds).toEqual(['k:const', 'v:x', 'p:=', 'f:fetch', 'p:(', "s:'a'", 'p:,', 'n:42', 'p:)', 'm:// why'])
  })

  it('carries a block comment over lines, and reads JSON keys', () => {
    const rows = rowsOf('/* one\ntwo */ return 1', 80, 'JavaScript')
    expect(rows[1].parts[0]).toEqual({ t: 'two */', k: 'm' })
    expect(rows[1].parts.find((p: any) => p.t === 'return').k).toBe('c')
    const json = rowsOf('{ "id": "clock" }', 80, 'JSON')[0].parts
    expect(json.find((p: any) => p.t === '"id"').k).toBe('v')
    expect(json.find((p: any) => p.t === '"clock"').k).toBe('s')
  })

  it('cuts a long line into rows, numbered where it starts', () => {
    const rows = rowsOf('abcdefghij\nk', 4, 'Plain Text')
    expect(rows.map((r: any) => [r.n, r.parts.map((p: any) => p.t).join('')])).toEqual([
      [1, 'abcd'], [0, 'efgh'], [0, 'ij'], [2, 'k'],
    ])
  })
})

describe('the code editor', () => {
  it('lists the frame scenes and opens one as files', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] } })
    host({ clock: SCENE })
    expect(screen(app)).toContain('Clock')
    find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).includes('Clock')).props.onClick({})
    const shown = screen(app)
    expect(shown).toContain('scene.json')
    expect(shown).toContain('"id": "clock",')
  })

  it('opens on the scene the scene settings asked for', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    host({ clock: SCENE })
    expect(screen(app)).toContain('"name": "Clock",')
    expect(app.state.open).toBe('')
  })

  it('changes a page and saves the scene back', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const code = host({ clock: SCENE })
    screen(app)
    // The explorer: the app's folder and its files.
    find(render(app), (n) => n.props && n.props.onClick && texts(n.props.children).includes('app.tsx')).props.onClick({})
    tap(app, 'Edit')
    const field = find(render(app), (n) => n.type === 'textarea')
    expect(field.props.value).toContain('12:00')
    field.props.onChange({ value: 'export function get() {\n  return <div>13:00</div>\n}\n', target: { value: 'export function get() {\n  return <div>13:00</div>\n}\n' } })
    tap(app, 'Done')
    expect(screen(app)).toContain('13:00')
    tap(app, 'Save')
    const saved = code.calls.find((call: any[]) => call[0] === 'save')
    expect(saved[1].show).toBe(false)
    expect(saved[1].scene.id).toBe('clock')
    expect(saved[1].scene.apps.clockFace.sources['app.tsx']).toContain('13:00')
  })

  it('asks the AI for a change with the scene as it is, and opens the draft', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }] }, state: { open: 'clock' } })
    const sources: Record<string, any> = { clock: SCENE }
    const facts: any = { ...FACTS }
    const code = host(sources, facts)
    screen(app)
    tap(app, 'Ask AI')
    find(render(app), (n) => n.type === 'textarea').props.onChange({ value: 'Bigger', target: { value: 'Bigger' } })
    tap(app, 'Ask')
    const asked = code.calls.find((call: any[]) => call[0] === 'ask')
    expect(asked[1].prompt).toBe('Bigger')
    expect(asked[1].scene.id).toBe('clock')
    // The plane answers: a draft.
    sources['\u0001draft'] = { ...SCENE, name: 'Big clock' }
    Object.assign(facts, { done: 'ask', draft: { id: 'clock', name: 'Big clock', summary: 'A bigger clock.' } })
    const shown = screen(app)
    expect(shown).toContain('Big clock — Code editor')
    expect(shown).toContain('AI draft')
    expect(shown).toContain('A bigger clock.')
    tap(app, 'Save & show')
    expect(code.calls.find((call: any[]) => call[0] === 'save')[1].show).toBe(true)
  })

  it('says why the AI refused', () => {
    const app = makeApp({ frame: { scenes: [] } })
    const facts: any = { ...FACTS }
    host({}, facts)
    tap(app, 'New scene with AI')
    find(render(app), (n) => n.type === 'textarea').props.onChange({ value: 'A clock', target: { value: 'A clock' } })
    tap(app, 'Ask')
    Object.assign(facts, { error: 'ai_unavailable' })
    expect(screen(app)).toContain('no AI to ask')
  })

  it('says when the settings on the screen are off', () => {
    const app = makeApp({ frame: { scenes: [] } })
    mock.code(() => null)
    expect(screen(app)).toContain("frame's settings on its screen")
  })
